pub(crate) fn materialize_case_foundation(case_index:u32,candidate:ValidatedEvaluationPayloadV1,texture_plan:EvaluationTexturePlanV1)->Option<EvaluationLoweringFoundationV1>{
let (generation,canvas_width,canvas_height,direct_projected_scalar_count,derived_evaluation_mesh_count,mask_edge_count)=case_metadata(case_index)?;
Some(EvaluationLoweringFoundationV1{generation,candidate,texture_plan,canvas_width,canvas_height,reservation_plan:materialize_case_plan(case_index)?,direct_projected_scalar_count,derived_evaluation_mesh_count,mask_edge_count})}
